"""End-of-run hooks for Copilot v2.

Hosts the ``EndOfRunHook`` contract plus its concrete implementations. A hook is
invoked at the end of a run, just before RUN_FINISHED; it receives the run
context and yields any final AG-UI events to emit (zero, one, or many). The
agent relays whatever a hook yields and stays agnostic about their meaning.
"""

from __future__ import annotations

import uuid
from collections.abc import AsyncIterator, Awaitable, Callable, Sequence
from typing import TYPE_CHECKING, Any

import structlog
from pydantic_ai import RunContext

from rasa.builder.copilot.pydantic_ai import ag_ui_events
from rasa.builder.copilot.pydantic_ai.persisted_messages import rows_from_run_messages
from rasa.builder.copilot.pydantic_ai.run_context import CopilotRunContext
from rasa.builder.models import GitCommitInfo

if TYPE_CHECKING:
    from pydantic_ai.messages import ModelMessage
    from pydantic_ai.run import AgentRunResult

    from rasa.builder.copilot.pydantic_ai.thread_store import ThreadStore
    from rasa.builder.project_generator import ProjectGenerator

structlogger = structlog.get_logger()

EndOfRunHook = Callable[[CopilotRunContext], AsyncIterator[dict[str, object]]]

# Signature of PydanticAI's native ``after_run`` hook: it receives the run
# context plus the run result and must return a (possibly replaced) result.
AfterRunHook = Callable[..., "Awaitable[AgentRunResult[Any]]"]

_COMMIT_AUTHOR = "Bot Builder"


def build_commit_hook(
    project_generator: "ProjectGenerator",
    email: str,
) -> EndOfRunHook:
    """Build the end-of-run commit hook for one Copilot v2 request.

    When the run changed project files, the hook persists the final written
    files and yields a CUSTOM ``commit_info`` AG-UI event; otherwise it yields
    nothing.
    """

    async def commit_changed_files(
        run_context: CopilotRunContext,
    ) -> AsyncIterator[dict[str, object]]:
        # Committing is a no-op unless the run actually wrote project files.
        if not run_context.made_changes:
            return

        git_service = project_generator.git_service
        # The commit must hold the git operation lock: unsafe_commit_changes runs
        # `git add`/`git commit`, which git_service rejects unless the lock is
        # held (and then silently swallows, returning the old HEAD).
        async with git_service.git_operation():
            previous_sha = await git_service.get_current_commit_sha()
            commit_sha = await project_generator.unsafe_commit_changes(
                GitCommitInfo(author=_COMMIT_AUTHOR, email=email, message=None)
            )

        # unsafe_commit_changes returns the unchanged HEAD when nothing was
        # staged or the commit failed. Don't claim a commit that never happened.
        if commit_sha == previous_sha:
            structlogger.warning(
                "copilot_v2.commit_hook.no_commit_created",
                commit_sha=commit_sha,
            )
            return

        commit = await git_service.get_commit_info(commit_sha)

        structlogger.info(
            "copilot_v2.commit_hook.done",
            commit_sha=commit_sha,
        )
        yield ag_ui_events.commit_info(
            {
                "commitSha": commit_sha,
                "commit": commit,
            }
        )

    return commit_changed_files


def build_persist_after_run_hook(thread_store: "ThreadStore") -> AfterRunHook:
    """Build a PydanticAI ``after_run`` hook that persists the completed turn.

    ``after_run`` fires once the agent run finishes (side-effect only): it reads
    the AG-UI messages accumulated on :class:`CopilotRunContext` during streaming
    and appends them to ``thread_store``. Persistence is best-effort — a storage
    failure is logged and swallowed so it never aborts a run the user already
    saw stream successfully. The hook returns the result unchanged.
    """

    async def persist_turn(
        ctx: RunContext[CopilotRunContext],
        *,
        result: "AgentRunResult[Any]",
    ) -> "AgentRunResult[Any]":
        run_context = ctx.deps
        try:
            messages = build_turn_messages(run_context, result.new_messages())
            if messages:
                await thread_store.append_messages(
                    run_context.request.thread_id, messages
                )
                structlogger.info(
                    "copilot_v2.persist.done",
                    thread_id=run_context.request.thread_id,
                    message_count=len(messages),
                )
        except Exception as exc:
            structlogger.warning(
                "copilot_v2.persist.failed",
                thread_id=run_context.request.thread_id,
                error=str(exc),
            )
        return result

    return persist_turn


def build_turn_messages(
    run_context: CopilotRunContext,
    new_messages: "Sequence[ModelMessage]",
) -> list[dict[str, Any]]:
    """Assemble the AG-UI messages for the just-completed turn, in stream order.

    The assistant rows come straight from pydantic-ai's own ordered record of
    the run (``new_messages``): reasoning, assistant text, and tool-call rows
    appear exactly in the order the model produced them — interleaved rather
    than grouped by role — so a rehydrated thread reads exactly as it streamed
    (reasoning -> tool -> text -> tool -> text -> ...). Each assistant text row
    and each tool-call row is its own message; text and tool calls are never
    merged into one row.

    The latest user message is prepended from the request (not read from
    ``new_messages``, whose prompt part carries the concatenated history). Only
    that one user message is persisted, since the client resends full history
    each turn and persisting all of it would duplicate earlier turns.
    """
    messages: list[dict[str, Any]] = []

    request_messages = run_context.request.messages
    if request_messages and request_messages[-1].role == "user":
        messages.append(
            {
                "id": uuid.uuid4().hex,
                "role": "user",
                "content": request_messages[-1].content,
            }
        )

    messages.extend(rows_from_run_messages(new_messages))
    return messages
